import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    .reg .u32 %r<20>;
    .reg .u64 %rd<24>;
    .reg .f32 %f<8>;
    .reg .pred %p<8>;

    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1, [M];
    ld.param.u32 %r2, [N];
    ld.param.u32 %r3, [K];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r4, %ctaid.y;
    mov.u32 %r5, %ntid.y;
    mov.u32 %r6, %tid.y;
    mad.lo.u32 %r7, %r4, %r5, %r6;   // row

    mov.u32 %r8, %ctaid.x;
    mov.u32 %r9, %ntid.x;
    mov.u32 %r10, %tid.x;
    mad.lo.u32 %r11, %r8, %r9, %r10; // col

    setp.ge.u32 %p1, %r7, %r1;
    setp.ge.u32 %p2, %r11, %r2;
    or.pred %p3, %p1, %p2;
    @%p3 bra DONE;

    // A row base pointer: A + row*K*4
    cvt.u64.u32 %rd4, %r7;
    cvt.u64.u32 %rd5, %r3;
    mul.lo.u64 %rd6, %rd4, %rd5;
    mul.lo.u64 %rd7, %rd6, 4;
    add.u64 %rd8, %rd1, %rd7;        // A row ptr

    // B col base pointer: B + col*4
    cvt.u64.u32 %rd9, %r11;
    mul.lo.u64 %rd10, %rd9, 4;
    add.u64 %rd11, %rd2, %rd10;      // B col ptr

    cvt.u64.u32 %rd12, %r2;
    mul.lo.u64 %rd13, %rd12, 4;      // row stride of B in bytes (N*4)

    mov.f32 %f1, 0f00000000;

    mov.u32 %r12, 0;
LOOP_START:
    setp.ge.u32 %p4, %r12, %r3;
    @%p4 bra LOOP_END;

    cvt.u64.u32 %rd14, %r12;
    mul.lo.u64 %rd15, %rd14, 4;
    add.u64 %rd16, %rd8, %rd15;
    ld.global.f32 %f2, [%rd16];      // A[row,k]

    mul.lo.u64 %rd17, %rd14, %rd13;
    add.u64 %rd18, %rd11, %rd17;
    ld.global.f32 %f3, [%rd18];      // B[k,col]

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.u32 %r12, %r12, 1;
    bra LOOP_START;
LOOP_END:

    // C[row,col] = row*N + col
    cvt.u64.u32 %rd19, %r7;
    mul.lo.u64 %rd20, %rd19, %rd12;
    add.u64 %rd21, %rd20, %rd9;
    mul.lo.u64 %rd22, %rd21, 4;
    add.u64 %rd23, %rd3, %rd22;
    st.global.f32 [%rd23], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B) with a large K dimension,
    implemented via a custom PTX kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32

        A = A.contiguous()
        B = B.contiguous()

        M, K = A.shape
        K2, N = B.shape
        assert K == K2

        C = torch.empty((M, N), dtype=torch.float32, device=A.device)

        module = _get_ptx_module()

        block_x = 16
        block_y = 16
        grid_x = (N + block_x - 1) // block_x
        grid_y = (M + block_y - 1) // block_y

        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, 1),
            block=(block_x, block_y, 1),
            arguments=[A, B, C, u32(M), u32(N), u32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

